    array_reserve_for_append(e, allocator, array, delta, 12);
    let size = e.mem.i32(array + 4);
    let data = e.mem.u32(array);
    let excess = size.wrapping_sub(count);
    let mut element = data.wrapping_add((count as u32).wrapping_mul(12));
    // Shrinking (not reached from a size of 0 unless `count` is negative).
    for _ in 0..excess.max(0) {
        let allocator = memory_allocator(e);
        e.mem.set_u32(element + 4, 0);
        array_free_storage(e, allocator, element, 8);
        e.mem.set_u32(element, 0);
        e.mem.set_u32(element + 8, 0x8000_0000);
        element = element.wrapping_add(12);
    }
    let size = e.mem.i32(array + 4);
    let missing = count.wrapping_sub(size);
