    if link & 0xffff_fffc == 0 {
        return false;
    }
    let vertex_a = e.mem.u32(triangle + TRIANGLE_VERTEX_0 + 4 * corner);
    let vertex_b = e
        .mem
        .u32(triangle + TRIANGLE_VERTEX_0 + 4 * next_corner(corner));
    let (owner, owner_edge) = if vertex_not_above(e, vertex_a, vertex_b) {
        (triangle, corner)
    } else {
        (link & 0xffff_fffc, link & 3)
    };
    if edge_is_marked(e, owner, owner_edge) {
        return false;
    }
    let previous = previous_corner(corner);
    let edge = link & 3;
    let neighbour = link & 0xffff_fffc;
    let apex_slot = previous_corner(edge);
    let vertex_o = e.mem.u32(neighbour + TRIANGLE_VERTEX_0 + 4 * apex_slot);
    let vertex_p = e.mem.u32(triangle + TRIANGLE_VERTEX_0 + 4 * previous);
    let (ox, oy) = (e.mem.i32(vertex_o + 8), e.mem.i32(vertex_o + 0xc));
