/// Frees the storage of the local array of positions of `00e1f4e0` (16 bytes per element of capacity,
/// when it owns it), leaves it empty and destroys the local hull.
fn release_fill_points(e: &mut Engine, s: u32) {
    let allocator = memory_allocator(e);
    let points = s + FILL_POINTS;
    e.mem.set_u32(points + 4, 0);
    array_free_storage(e, allocator, points, 16);
    e.mem.set_u32(points, 0);
    e.mem.set_u32(points + 8, 0x8000_0000);
    e.call(HULL_DESTRUCTOR, &args![s + 0x17c]);
}

