        put_vec(&mut e, direction, [1.0, 0.0, 0.0, 0.0]);
        let out = e.mem.alloc(0x10);
        // The list is walked newest first: 2.0 (index 0), 3.0 (index 1), 1.0 (index 2).
        let got = e.call(0x00e1_1570, &args![mesh, out, direction]).u32();
        assert_eq!(got, out);
