        let behind = add_vertex(&mut e, mesh, [-2.0, 0.0, 0.0, 1.0]);
        let near = add_vertex(&mut e, mesh, [1.25, 0.0, 0.0, 1.0]);
        let front = add_vertex(&mut e, mesh, [3.0, 0.0, 0.0, 1.0]);
        let plane = e.mem.alloc(0x10);
