        let plane = e.mem.alloc(0x10);
        put_vec(&mut e, plane, [1.0, 0.0, 0.0, -1.0]);
        assert_eq!(e.call(0x00e1_1990, &args![mesh, plane, 0u32]).u32(), 1);
        put_vec(&mut e, plane, [-1.0, 0.0, 0.0, -1.0]);
