        let b = e.mem.u32(triangle + 0xc);
        put_vec(&mut e, b + 0x10, [0.0, 0.0, 0.0, 0.0]);
        put_vec(&mut e, triangle + 0x20, [5.0, 5.0, 5.0, 5.0]);
