        let second = add_vertex(&mut e, mesh, [0.0; 4]);
        e.call(0x00e1_1da0, &args![mesh, 0xabcd_u32]);
        assert_eq!(e.mem.u32(first + 0x44), 0xabcd);
        assert_eq!(e.mem.u32(second + 0x44), 0xabcd);
