        // Each pool: the empty array's storage (data 0, 0 bytes) is "freed" and flagged empty.
        assert_eq!(*log.borrow(), vec![(0x10, 0, 0), (0x10, 0, 0)]);
        assert_eq!(e.mem.u32(mesh + 0x28), 0x8000_0000);
